package tw.aihankapps.timehut;

import android.content.Context;
import android.util.AtomicFile;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;

/** Actual Android Keystore and native HTTP with artificial users only. */
public class AccountNativeLoginAdmissionTest {
    private int controls;
    private static byte[] read(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    private static String epoch(AccountSessionStore store)throws Exception{return store.bridgeStatus().getString("generation");}
    private interface Failing {void run()throws Exception;}
    private static void denied(Failing action)throws Exception{try{action.run();fail("Unconfirmed account transition must be refused");}catch(IOException expected){}}
    private static String token(){return "synthetic_native_"+UUID.randomUUID().toString().replace("-","");}
    @Test public void durableAdmissionCancellationAndUnknownReply()throws Exception{
        assertTrue(BuildConfig.DEBUG);assertTrue(android.os.Build.VERSION.SDK_INT>=36);Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();File dir=new File(context.getNoBackupFilesDir(),"native-admission-qa-"+UUID.randomUUID());assertTrue(dir.mkdir());String alias="timehut.native-admission.qa."+UUID.randomUUID();
        JSONObject report=new JSONObject().put("status","UNCONFIRMED").put("providerRequests",0).put("dataReset",false).put("actualColdProcess",false).put("actualWebView",false);
        String phase="unit-first-admission";
        try{
            File file=new File(dir,"admission.json");AccountSessionStore store=new AccountSessionStore(file,alias);String before=epoch(store);JSONObject admitted=store.beginLogin(AccountIdentity.BACKEND,before);assertEquals(before,epoch(store));assertTrue(store.bridgeStatus().getBoolean("loginPending"));assertEquals(1,store.bridgeStatus().getInt("pendingLoginReceipts"));String text=new String(read(file),StandardCharsets.UTF_8);assertFalse(text.contains(admitted.getString("secret")));assertFalse(store.bridgeStatus().toString().contains(admitted.getString("id")));assertFalse(store.bridgeStatus().toString().contains(admitted.getString("secret")));assertEquals(2,new JSONObject(text).getInt("version"));store.requireLogin(admitted.getString("id"));controls++;
            byte[] unchanged=read(file);denied(()->store.beginLogin(AccountIdentity.BACKEND,epoch(store)));assertArrayEquals(unchanged,read(file));controls++;
            String issued=token(),owner=UUID.randomUUID().toString();long expiry=System.currentTimeMillis()+3600000;store.captureLoginToken(admitted.getString("id"),issued);assertFalse(new String(read(file),StandardCharsets.UTF_8).contains(issued));assertNull(store.currentOwner());controls++;
            store.signOut();assertFalse(store.bridgeStatus().getBoolean("loginPending"));assertEquals(1,store.nativeCancellations().length());denied(()->store.completeLogin(admitted.getString("id"),owner,issued,expiry,false,AccountIdentity.BACKEND));assertNull(store.currentOwner());controls++;
            JSONObject wrong=new JSONObject(admitted.toString()).put("secret","A".repeat(43));assertFalse(store.confirmNativeCancellation(wrong));assertEquals(1,store.nativeCancellations().length());assertTrue(store.confirmNativeCancellation(admitted));assertEquals(0,store.bridgeStatus().getInt("pendingLoginReceipts"));controls++;
            JSONObject accepted=store.beginLogin(AccountIdentity.BACKEND,epoch(store));store.captureLoginToken(accepted.getString("id"),issued);store.completeLogin(accepted.getString("id"),owner,issued,expiry,false,AccountIdentity.BACKEND);assertEquals(owner,new AccountSessionStore(file,alias).currentOwner());assertEquals(0,store.bridgeStatus().getInt("pendingLoginReceipts"));controls++;
            JSONObject next=store.beginLogin(AccountIdentity.BACKEND,epoch(store));String nextToken=token();store.signOut();store.captureLoginToken(next.getString("id"),nextToken);denied(()->store.completeLogin(next.getString("id"),UUID.randomUUID().toString(),nextToken,expiry,false,AccountIdentity.BACKEND));assertTrue(store.pendingRevocation(owner,issued,AccountIdentity.BACKEND));assertEquals(1,store.nativeCancellations().length());assertTrue(store.confirmNativeCancellation(next));assertTrue(store.confirmRevocation(owner,issued,AccountIdentity.BACKEND));controls++;
            JSONObject first=store.beginLogin(AccountIdentity.BACKEND,epoch(store));store.abortLogin(first.getString("id"));JSONObject second=store.beginLogin(AccountIdentity.BACKEND,epoch(store));store.abortLogin(second.getString("id"));assertTrue(store.beginNativeCancellation(first));JSONArray fair=new AccountSessionStore(file,alias).nativeCancellations();assertEquals(second.getString("id"),fair.getJSONObject(0).getString("id"));assertEquals(first.getString("id"),fair.getJSONObject(1).getString("id"));store.confirmNativeCancellation(first);store.confirmNativeCancellation(second);controls++;
            phase="unit-new-authority";File copy=new File(dir,"new-authority.json");JSONObject interrupted=store.beginLogin(AccountIdentity.BACKEND,epoch(store));try(FileOutputStream out=new FileOutputStream(copy)){out.write(read(file));out.getFD().sync();}AccountSessionStore fresh=new AccountSessionStore(copy,alias);assertFalse(fresh.bridgeStatus().getBoolean("loginPending"));assertEquals(interrupted.getString("id"),fresh.nativeCancellations().getJSONObject(0).getString("id"));assertNull(fresh.currentOwner());store.abortLogin(interrupted.getString("id"));controls++;
            phase="unit-write-failure";File failure=new File(dir,"io.json");AccountSessionStore io=new AccountSessionStore(failure,alias);io.enableAccountMode();AccountSessionStore broken=new AccountSessionStore(failure,alias,new AccountSessionStore.CommitOps(){public void sync(FileOutputStream output)throws Exception{throw new IOException("Synthetic admission sync interruption");}public void finish(AtomicFile target,FileOutputStream output){target.finishWrite(output);}});denied(()->broken.beginLogin(AccountIdentity.BACKEND,epoch(broken)));denied(()->new AccountSessionStore(failure,alias));assertTrue(new File(failure+".intent").isFile());
            File recovery=new File(dir,"recovery.json");for(String suffix:new String[]{"",".intent",".intent.tmp",".new",".bak"}){File original=new File(failure+suffix);if(original.exists())try(FileOutputStream out=new FileOutputStream(recovery+suffix)){out.write(read(original));out.getFD().sync();}}AccountSessionStore recovered=new AccountSessionStore(recovery,alias);assertNull(recovered.currentOwner());assertEquals(1,recovered.nativeCancellations().length());assertFalse(recovered.bridgeStatus().getBoolean("loginPending"));controls++;
            phase="unit-capacity";File capacityFile=new File(dir,"capacity.json");AccountSessionStore capacity=new AccountSessionStore(capacityFile,alias);for(int i=0;i<23;i++)capacity.activateVerified(UUID.randomUUID().toString(),token(),expiry,false);byte[] full=read(capacityFile);denied(()->capacity.beginLogin(AccountIdentity.BACKEND,epoch(capacity)));assertArrayEquals(full,read(capacityFile));capacity.signOut();assertEquals(23,capacity.pendingRevocations().length());controls++;
            phase="native-http-unknown-result";TransferEngine.initialize(context);assertNull("Unknown active account preserved",TransferEngine.accounts().currentOwner());assertEquals(0,TransferEngine.accounts().pendingRevocations().length());assertEquals(0,TransferEngine.accounts().bridgeStatus().getInt("pendingLoginReceipts"));
            try(AccountClientBridgeTest.Fixture fixture=new AccountClientBridgeTest.Fixture()){
                fixture.holdNativeReply=true;fixture.offlineNativeCancel=true;ExecutorService worker=Executors.newSingleThreadExecutor();Future<JSONObject> pending=worker.submit(()->AccountClient.signIn(fixture.endpoint(),"synthetic-alpha","artificial-native-secret","人工甲",true));
                try{
                    assertTrue(fixture.nativeIssued.await(5,TimeUnit.SECONDS));assertEquals(1,TransferEngine.accounts().bridgeStatus().getInt("pendingLoginReceipts"));assertTrue(TransferEngine.accounts().bridgeStatus().getBoolean("loginPending"));assertNull(TransferEngine.accounts().currentOwner());
                    AccountClient.Logout logout=AccountClient.beginSignOut(null,AccountClient.bridgeStatus().getString("generation"));assertFalse(AccountClient.finishSignOut(logout).getBoolean("serverConfirmed"));assertFalse(TransferEngine.accounts().bridgeStatus().getBoolean("authenticated"));controls++;
                    fixture.releaseNativeReply.countDown();try{pending.get(8,TimeUnit.SECONDS);fail("Cancelled in-flight login must never activate");}catch(ExecutionException expected){}assertNull(TransferEngine.accounts().currentOwner());assertEquals(1,fixture.nativeLoginPosts.get());JSONArray rows=TransferEngine.accounts().nativeCancellations();assertEquals(1,rows.length());assertEquals(fixture.lastToken,rows.getJSONObject(0).getString("token"));String encrypted=new String(read(new File(context.getNoBackupFilesDir(),"accounts/session.json")),StandardCharsets.UTF_8);assertFalse(encrypted.contains(fixture.lastToken));assertFalse(encrypted.contains(rows.getJSONObject(0).getString("secret")));controls++;
                    fixture.offlineNativeCancel=false;fixture.wrongNativeCancelAck=true;assertFalse(AccountClient.drainNativeCancellation(fixture.endpoint()));assertEquals(1,TransferEngine.accounts().nativeCancellations().length());fixture.wrongNativeCancelAck=false;assertTrue(AccountClient.drainNativeCancellation(fixture.endpoint()));assertEquals(0,TransferEngine.accounts().nativeCancellations().length());assertFalse(fixture.tokens.containsKey(fixture.lastToken));assertEquals(1,fixture.nativeLoginPosts.get());controls++;
                    phase="native-http-profile-failure";fixture.holdNativeReply=false;fixture.profileUnavailable=true;fixture.offlineNativeCancel=true;denied(()->AccountClient.signIn(fixture.endpoint(),"synthetic-alpha","artificial-native-secret","",false));assertNull(TransferEngine.accounts().currentOwner());assertEquals(1,TransferEngine.accounts().nativeCancellations().length());fixture.profileUnavailable=false;fixture.offlineNativeCancel=false;assertTrue(AccountClient.drainNativeCancellation(fixture.endpoint()));assertEquals(0,TransferEngine.accounts().nativeCancellations().length());controls++;
                    phase="native-http-positive";String loginEpoch=AccountClient.bridgeStatus().getString("generation");JSONObject positive=AccountClient.signIn(fixture.endpoint(),"synthetic-alpha","artificial-native-secret","",false);assertFalse(positive.toString().contains(fixture.lastToken));assertEquals(fixture.users.get("synthetic-alpha").getString("id"),TransferEngine.accounts().currentOwner());assertEquals(0,TransferEngine.accounts().bridgeStatus().getInt("pendingLoginReceipts"));assertTrue(AccountClient.finishSignOut(AccountClient.beginSignOut(null,loginEpoch,true)).getBoolean("serverConfirmed"));assertNull(TransferEngine.accounts().currentOwner());controls++;
                    phase="native-postcommit-cancel-fence";String originalEpoch=AccountClient.bridgeStatus().getString("generation");AccountClient.signIn(fixture.endpoint(),"synthetic-alpha","artificial-native-secret","",false);denied(()->AccountClient.beginSignOut(null,originalEpoch,false));assertNotNull(TransferEngine.accounts().currentOwner());assertTrue(AccountClient.finishSignOut(AccountClient.beginSignOut(null,originalEpoch,true)).getBoolean("serverConfirmed"));assertNull(TransferEngine.accounts().currentOwner());controls++;
                    phase="native-postcommit-preserve-new-B";String oldEpoch=AccountClient.bridgeStatus().getString("generation");AccountClient.signIn(fixture.endpoint(),"synthetic-alpha","artificial-native-secret","",false);String bOwner=UUID.randomUUID().toString();TransferEngine.accounts().activateVerified(bOwner,token(),expiry,false,fixture.endpoint());denied(()->AccountClient.beginSignOut(null,oldEpoch,true));assertEquals(bOwner,TransferEngine.accounts().currentOwner());AccountClient.signOut();for(int i=0;i<5&&TransferEngine.accounts().pendingRevocations().length()>0;i++)AccountClient.drainRevocation(fixture.endpoint());controls++;
                }finally{fixture.releaseNativeReply.countDown();fixture.offlineNativeCancel=false;fixture.wrongNativeCancelAck=false;fixture.profileUnavailable=false;worker.shutdownNow();worker.awaitTermination(3,TimeUnit.SECONDS);for(int i=0;i<4&&TransferEngine.accounts().nativeCancellations().length()>0;i++)AccountClient.drainNativeCancellation(fixture.endpoint());}
            }
            assertEquals(0,TransferEngine.accounts().bridgeStatus().getInt("pendingLoginReceipts"));assertEquals(0,TransferEngine.accounts().pendingRevocations().length());report.put("status","PASS_ANDROID_NATIVE_LOGIN_ADMISSION").put("unitControls",11).put("nativeHTTPControls",7).put("actualKeystore",true).put("finalMainPending",0);
        }finally{report.put("controls",controls).put("lastPhase",phase);try(FileOutputStream out=new FileOutputStream(new File(context.getFilesDir(),"native-login-admission-report.json"))){out.write(report.toString(2).getBytes(StandardCharsets.UTF_8));out.getFD().sync();}}
    }
}
